"""Driver for the Brevalt KX-100 RF power meter. The programming manual is MANUAL.md.

`session` is an open connection to the meter with three methods:
    session.write(cmd: str) -> None
    session.read() -> str
    session.query(cmd: str) -> str      # write, then read
"""

import math

_MAX_ERROR_READS = 32  # the queue holds 10 errors; this only guards against a misbehaving session


class InstrumentError(Exception):
    """The meter reported an error: SYST:ERR? returned a code other than 0."""


def _format_number(value) -> str:
    """Format a numeric parameter without losing precision (the meter accepts plain decimals)."""
    if isinstance(value, bool):
        return str(int(value))
    if isinstance(value, int):
        return str(value)
    return repr(float(value))


def _drain_errors(session) -> list:
    """Read SYST:ERR? until it returns code 0; return the list of non-zero error responses."""
    errors = []
    for _ in range(_MAX_ERROR_READS):
        response = session.query("SYST:ERR?").strip()
        code_text = response.split(",", 1)[0].strip()
        try:
            code = int(code_text)
        except ValueError:
            errors.append(f"unparseable SYST:ERR? response: {response!r}")
            break
        if code == 0:
            return errors
        errors.append(response)
    else:
        errors.append("error queue did not empty")
    return errors


def measure_power(session, freq_hz: float, averages: int) -> float:
    """Measure the power of a signal at `freq_hz`, averaging `averages` readings, and return it in dBm.

    Raise InstrumentError if the meter reports any error while configuring or measuring.
    """
    # 1. Start from an empty error queue so every error seen below belongs to this measurement.
    session.write("*CLS")
    # 2-4. Configure: signal frequency (selects the calibration factor), averaging, range.
    session.write(f"SENS:FREQ {_format_number(freq_hz)}")
    session.write(f"SENS:AVER:COUN {_format_number(averages)}")
    session.write("CONF:POW:RANG AUTO")
    # 5-6. Take a new measurement and wait for it to complete (FETC? alone never measures).
    session.write("INIT")
    opc = session.query("*OPC?").strip()
    # 7. Read the result of that measurement.
    fetched = session.query("FETC?").strip()
    # 8. Any queued error invalidates the reading.
    errors = _drain_errors(session)
    if errors:
        raise InstrumentError("KX-100 reported: " + "; ".join(errors))
    if opc != "1":
        raise InstrumentError(f"unexpected *OPC? response: {opc!r}")
    try:
        value = float(fetched)
    except ValueError as e:
        raise InstrumentError(f"unparseable FETC? response: {fetched!r}") from e
    if not math.isfinite(value) or value >= 9.9e37:
        raise InstrumentError(f"invalid measurement: {fetched}")
    return value

